#include "fm.hpp"
struct Dynamic {State m;int step=0,cross=0;double cumulative=0,maxraw=0,left=0,right=0,interpolated=0;};
V mean_d(const State&m){V v{};for(auto q:m[0])v+=q*(1./m[0].size());return v;}
void save_d(const std::filesystem::path&p,const Dynamic&s,const Config&c){write_state(p.string()+".state",c,s.m,s.step,s.cumulative);std::ofstream f(p.string()+".meta");f<<"FM-D1NS-v1\n"<<c.signature()<<'\n'<<s.cross<<' '<<std::setprecision(17)<<s.maxraw<<' '<<s.left<<' '<<s.right<<' '<<s.interpolated<<'\n'<<file_sha256(p.string()+".state")<<'\n';f.flush();if(!f)throw std::runtime_error("D1NS meta write");}
Dynamic load_d(const std::filesystem::path&p,const Config&c,const std::string&wanted="FM-D1NS-v1"){std::ifstream f(p.string()+".meta");std::string magic,sig,h;std::getline(f,magic);std::getline(f,sig);Dynamic s;f>>s.cross>>s.maxraw>>s.left>>s.right>>s.interpolated>>h;if(!f||magic!=wanted||sig!=c.signature()||h!=file_sha256(p.string()+".state")||s.cross<0||s.cross>c.steps||s.maxraw>1e-8||!std::isfinite(s.maxraw))throw std::runtime_error("D1NS restore signature/meta");s.m=read_state(p.string()+".state",c,s.step,s.cumulative);if(s.cross>s.step)throw std::runtime_error("D1NS restore crossing count");return s;}
void frame_d(const std::filesystem::path&p,const State&m,const Evaluation&e){std::ofstream f(p);f<<std::setprecision(17)<<"cell,mx,my,mz,Hx,Hy,Hz\n";for(size_t j=0;j<m[0].size();j++){auto q=m[0][j],h=e.H[0][j];f<<j<<','<<q.x<<','<<q.y<<','<<q.z<<','<<h.x<<','<<h.y<<','<<h.z<<'\n';}f.flush();if(!f)throw std::runtime_error("D1NS frame write");}
int main(int argc,char**argv){std::filesystem::path out;bool made=false;Dynamic s;std::unique_ptr<Model>model;
 try{if(argc!=6)throw std::runtime_error("CONFIG NEW_OUTPUT RESTORE_PREFIX_OR_DASH GLOBAL_END IMPORT_SOURCE_CONFIG_OR_DASH");auto begin=Clock::now();Config c=read_config(argv[1]);int end=std::stoi(argv[4]);if(!((c.nx==100&&c.ny==25&&c.h==std::array<double,3>{5e-9,5e-9,3e-9})||(c.nx==200&&c.ny==50&&c.h==std::array<double,3>{2.5e-9,2.5e-9,3e-9}))||c.Ms!=8e5||c.A!=1.3e-11||c.K!=0||c.alpha!=.02||c.grel!=1||c.gamma_G!=221088.4||(c.dt!=50e-15&&c.dt!=100e-15)||c.steps!=(c.dt==50e-15?20000:10000)||c.active!=std::array<int,4>{1,0,1,1}||std::abs(c.H.x*mu0+.0246)>1e-17||std::abs(c.H.y*mu0-.0043)>1e-17||c.H.z!=0||end<1||end>c.steps)throw std::runtime_error("D1NS frozen SP4 scope");for(auto x:c.fixed)if(x)throw std::runtime_error("D1NS all free");out=argv[2];if(std::filesystem::exists(out))throw std::runtime_error("D1NS no overwrite");std::filesystem::create_directories(out);made=true;model=std::make_unique<Model>(c);s.m=c.m;if(std::string(argv[5])!="-"){Config original=read_config(argv[5]);if(std::string(argv[3])=="-"||c.nx!=200||c.dt!=50e-15||original.steps!=4000||original.nx!=c.nx||original.ny!=c.ny||original.h!=c.h||original.Ms!=c.Ms||original.A!=c.A||original.K!=c.K||original.alpha!=c.alpha||original.grel!=c.grel||original.gamma_G!=c.gamma_G||original.dt!=c.dt||original.active!=c.active||norm(original.H-c.H)!=0||norm(original.axis-c.axis)!=0||original.fixed!=c.fixed||original.initial_sha256!=c.initial_sha256||original.kernel_sha256!=c.kernel_sha256)throw std::runtime_error("D1NS explicit import physical/initial identity");s=load_d(argv[3],original,"FM-D200-v1");if(s.step!=4000)throw std::runtime_error("D1NS import200ps only");std::ofstream lineage(out/"import_lineage.txt");lineage<<"explicit_D200_to_D1NS_import\n"<<file_sha256(argv[5])<<'\n'<<file_sha256(std::string(argv[3])+".state")<<'\n'<<file_sha256(std::string(argv[3])+".meta")<<'\n'<<original.signature()<<'\n'<<c.signature()<<'\n'<<std::setprecision(17)<<s.step<<' '<<s.cumulative<<' '<<s.maxraw<<' '<<s.cross<<' '<<s.left<<' '<<s.right<<' '<<s.interpolated<<'\n';lineage.flush();if(!lineage)throw std::runtime_error("D1NS import lineage write");save_d(out/"imported",s,c);}else if(std::string(argv[3])!="-")s=load_d(argv[3],c);int start=s.step;auto check=[&]{if(std::chrono::duration<double>(Clock::now()-begin).count()>29.8||rss()>2147483648)throw std::runtime_error("D1NS resource cap");};auto eval=[&](const State&m){auto e=model->eval(m);check();return e;};auto rhs=[&](const State&m,const Evaluation&e){return model->rhs(m,e);};auto loss=[&](const State&m,const Evaluation&e){return model->loss(m,e);};auto current=eval(s.m);V prevMean=mean_d(s.m);
 std::ofstream hist(out/"history.csv"),sample(out/"sample_1ps.csv");hist<<std::setprecision(17)<<"step,time_s,E_J,loss_W,cumulative_loss_J,raw,mx,my,mz\n";sample<<std::setprecision(17)<<"step,time_s,mx,my,mz\n";auto row=[&](double raw){V avg=mean_d(s.m);hist<<s.step<<','<<s.step*c.dt<<','<<current.E<<','<<loss(s.m,current)[0]<<','<<s.cumulative<<','<<raw<<','<<avg.x<<','<<avg.y<<','<<avg.z<<'\n';hist.flush();if(s.step%c.stride==0){sample<<s.step<<','<<s.step*c.dt<<','<<avg.x<<','<<avg.y<<','<<avg.z<<'\n';sample.flush();}if(!hist||!sample)throw std::runtime_error("D1NS scalar write");};row(0);if(s.step==0){save_d(out/"initial",s,c);frame_d(out/"frame_0.csv",s.m,current);}double setup=std::chrono::duration<double>(Clock::now()-begin).count();double maxCycle=0,totalCycle=0,saveMax=0;
 while(s.step<end){auto tick=Clock::now();State old=s.m;auto previous=current;double oldLoss=s.cumulative,delta=0;State candidate=rk4_raw(s.m,c.dt,eval,rhs,loss,delta);double raw=project_endpoint(candidate);if(raw>1e-8)throw std::runtime_error("D1NS frozen raw norm gate");auto endpoint=eval(candidate);if(!std::isfinite(s.cumulative+delta))throw std::runtime_error("D1NS nonfinite loss");s.m=std::move(candidate);current=std::move(endpoint);s.step++;s.cumulative+=delta;s.maxraw=std::max(s.maxraw,raw);auto avg=mean_d(s.m);row(raw);
 if(!s.cross&&prevMean.x>0&&avg.x<=0){s.cross=s.step;s.left=(s.step-1)*c.dt;s.right=s.step*c.dt;s.interpolated=s.left+c.dt*prevMean.x/(prevMean.x-avg.x);write_state(out/"cross_before.state",c,old,s.step-1,oldLoss);write_state(out/"cross_after.state",c,s.m,s.step,s.cumulative);frame_d(out/"cross_before.csv",old,previous);frame_d(out/"cross_after.csv",s.m,current);save_d(out/"first_cross",s,c);}prevMean=avg;
 if(s.step%250==0){auto t=Clock::now();save_d(out/("checkpoint_"+std::to_string(s.step)),s,c);saveMax=std::max(saveMax,std::chrono::duration<double>(Clock::now()-t).count());}if(s.step==int(std::llround(100e-12/c.dt))||s.step==int(std::llround(138e-12/c.dt))||s.step==int(std::llround(139e-12/c.dt))||s.step==int(std::llround(200e-12/c.dt))||s.step==int(std::llround(500e-12/c.dt))||s.step==c.steps)frame_d(out/("frame_"+std::to_string(s.step)+".csv"),s.m,current);double cost=std::chrono::duration<double>(Clock::now()-tick).count();maxCycle=std::max(maxCycle,cost);totalCycle+=cost;check();}
 auto t=Clock::now();save_d(out/"final",s,c);frame_d(out/"final_frame.csv",s.m,current);double finalSave=std::chrono::duration<double>(Clock::now()-t).count();std::ofstream f(out/"summary.json");f<<std::setprecision(17)<<"{\"status\":\"segment_completed\",\"start_step\":"<<start<<",\"step\":"<<s.step<<",\"time_s\":"<<s.step*c.dt<<",\"cross_step\":"<<s.cross<<",\"cross_left_s\":"<<s.left<<",\"cross_right_s\":"<<s.right<<",\"cross_interpolated_s\":"<<s.interpolated<<",\"maxraw\":"<<s.maxraw<<",\"setup_s\":"<<setup<<",\"max_full_cycle_s\":"<<maxCycle<<",\"total_full_cycle_s\":"<<totalCycle<<",\"max_periodic_save_s\":"<<saveMax<<",\"final_checkpoint_frame_s\":"<<finalSave<<",\"field_calls\":"<<model->calls<<",\"wall_s\":"<<std::chrono::duration<double>(Clock::now()-begin).count()<<",\"rss\":"<<rss()<<"}\n";f.flush();if(!f)throw std::runtime_error("D1NS summary write");check();return 0;
 }catch(const std::exception&e){if(made&&model&&!s.m[0].empty()){try{save_d(out/"last_accepted",s,model->c);}catch(...){ }std::ofstream f(out/"failure.txt");f<<e.what()<<'\n';}std::cerr<<e.what();return 2;}}
